const body = $('Webhook Reserva (POST)').first().json.body || {};

function fail(msg){ return [{ json: { valido: false, erro: msg } }]; }

// Campos obrigatórios
const kitId = String(body.kit_id || '').trim();
const dataEvento = String(body.data_evento || '').slice(0, 10);
const nome = String(body.cliente_nome || '').trim();
const whatsapp = String(body.cliente_whatsapp || '').replace(/\D/g, '');
const metodo = String(body.metodo_pagamento || 'pix').toLowerCase();
const querMontagem = body.quer_montagem === true || body.quer_montagem === 'true';
const distanciaKm = Math.max(0, Number(body.distancia_km) || 0);
const endereco = String(body.endereco || '').trim();
const periodo = String(body.periodo || 'dia').trim();

if (!kitId) return fail('Kit não informado.');
if (!/^\d{4}-\d{2}-\d{2}$/.test(dataEvento)) return fail('Data do evento inválida.');
if (nome.length < 2) return fail('Informe o nome do cliente.');
if (whatsapp.length < 10) return fail('WhatsApp do cliente inválido.');
if (!['pix', 'mercadopago'].includes(metodo)) return fail('Método de pagamento inválido.');

// Kit existe e está ativo?
const kit = $('Ler Kits').all().map(i => i.json)
  .find(k => String(k.id) === kitId && String(k.ativo).toUpperCase() === 'SIM');
if (!kit) return fail('Kit indisponível.');

// Antecedência mínima
const antecedencia = Number($env.FESTAS_ANTECEDENCIA_MIN_DIAS || 2);
const hojeISO = $now.toFormat('yyyy-MM-dd');
const diffDias = Math.ceil((new Date(dataEvento + 'T00:00:00') - new Date(hojeISO + 'T00:00:00')) / 86400000);
if (diffDias < antecedencia) return fail(`Reserve com pelo menos ${antecedencia} dia(s) de antecedência.`);

// Data já ocupada?
const STATUS_OCUPA = ['AGUARDANDO_PAGAMENTO', 'PAGO', 'CONCLUIDO'];
const ocupada = $('Ler Reservas').all().map(i => i.json)
  .some(r => String(r.data_evento).slice(0,10) === dataEvento && STATUS_OCUPA.includes(String(r.status||'').toUpperCase()));
if (ocupada) return fail('Essa data já está reservada. Escolha outra.');

// Cálculo dos valores (server-side, fonte de verdade)
const precoKit = Number(kit.preco_locacao) || 0;
const taxaEntrega = Number($env.FESTAS_TAXA_ENTREGA_BASE || 0) + (Number($env.FESTAS_TAXA_ENTREGA_KM || 0) * distanciaKm);
const taxaMontagem = querMontagem ? (Number($env.FESTAS_TAXA_MONTAGEM) || 0) : 0;
const valorTotal = Math.round((precoKit + taxaEntrega + taxaMontagem) * 100) / 100;

// ID curto e único da reserva
const rid = 'R' + $now.format('yyMMdd') + '-' + $runIndex + '-' + Math.abs(($now.toMillis() % 100000)).toString().padStart(5,'0');
const reservaId = rid.replace(/[^A-Za-z0-9-]/g, '');

return [{ json: {
  valido: true,
  reserva_id: reservaId,
  criado_em: $now.format('DD/MM/YYYY HH:mm:ss'),
  kit_id: kitId,
  kit_nome: kit.nome,
  data_evento: dataEvento,
  periodo,
  cliente_nome: nome,
  cliente_whatsapp: whatsapp,
  endereco,
  distancia_km: distanciaKm,
  taxa_entrega: Math.round(taxaEntrega * 100) / 100,
  taxa_montagem: taxaMontagem,
  valor_kit: precoKit,
  valor_total: valorTotal,
  metodo_pagamento: metodo,
  status: 'AGUARDANDO_PAGAMENTO'
} }];

const r = $('Validar e Calcular').item.json;

function norm(s, max){
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9 ]/g, '').toUpperCase().trim().slice(0, max);
}
function tlv(id, value){
  const len = String(value.length).padStart(2, '0');
  return `${id}${len}${value}`;
}
function crc16(payload){
  let crc = 0xFFFF;
  for (let i = 0; i < payload.length; i++){
    crc ^= payload.charCodeAt(i) << 8;
    for (let j = 0; j < 8; j++){
      crc = (crc & 0x8000) ? ((crc << 1) ^ 0x1021) : (crc << 1);
      crc &= 0xFFFF;
    }
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

const chave = String($env.FESTAS_PIX_CHAVE || '').trim();
const nome = norm($env.FESTAS_PIX_NOME, 25) || 'RECEBEDOR';
const cidade = norm($env.FESTAS_PIX_CIDADE, 15) || 'BRASIL';
const valor = (Number(r.valor_total) || 0).toFixed(2);
const txid = norm(r.reserva_id, 25).replace(/ /g, '') || '***';

const mai = tlv('00', 'br.gov.bcb.pix') + tlv('01', chave);
let payload = ''
  + tlv('00', '01')
  + tlv('26', mai)
  + tlv('52', '0000')
  + tlv('53', '986')
  + tlv('54', valor)
  + tlv('58', 'BR')
  + tlv('59', nome)
  + tlv('60', cidade)
  + tlv('62', tlv('05', txid));
payload += '6304';
const brcode = payload + crc16(payload);

return [{ json: {
  ok: true,
  reserva_id: r.reserva_id,
  status: r.status,
  metodo_pagamento: 'pix',
  valor_total: r.valor_total,
  resumo: {
    kit_nome: r.kit_nome, data_evento: r.data_evento, periodo: r.periodo,
    valor_kit: r.valor_kit, taxa_entrega: r.taxa_entrega, taxa_montagem: r.taxa_montagem
  },
  pagamento: {
    tipo: 'pix',
    pix_copia_cola: brcode,
    chave: chave,
    instrucoes: 'Copie o código Pix e pague no app do seu banco. A reserva é confirmada assim que o pagamento for identificado.'
  }
} }];

